global_css:
/* UptimeFixer Safe Changes Manager - compact footer v1.2 */
.ufx-safe-footer,
.ufx-safe-footer * { box-sizing: border-box; }

.ufx-safe-footer {
  position: relative;
  width: 100%;
  overflow: hidden;
  background: #10202d;
  color: #f7fbff;
  font-family: inherit;
  border-top: 1px solid rgba(255,255,255,.07);
}

.ufx-safe-footer::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 3px;
  background: #c8f15a;
}

.ufx-safe-footer__inner {
  width: min(1320px, calc(100% - 56px));
  margin: 0 auto;
  padding: 46px 0 18px;
}

.ufx-safe-footer__top {
  display: grid;
  grid-template-columns: minmax(250px,1.05fr) minmax(320px,1.25fr) minmax(170px,.75fr) minmax(170px,.75fr);
  gap: 52px;
  align-items: start;
}

.ufx-safe-footer__brand {
  max-width: 330px;
}

.ufx-safe-footer__logo {
  display: inline-flex;
  align-items: center;
  margin: 0 0 20px;
  text-decoration: none !important;
}

.ufx-safe-footer__logo img,
.ufx-safe-footer__logo .custom-logo {
  display: block;
  width: auto;
  max-width: 205px;
  max-height: 58px;
  height: auto;
  object-fit: contain;
  background: #fff;
  padding: 7px 11px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,.12);
  box-shadow: 0 8px 22px rgba(0,0,0,.12);
}

.ufx-safe-footer__logo .custom-logo-link {
  display: inline-flex;
}

.ufx-safe-footer__logo-text {
  color: #fff;
  font-size: 22px;
  font-weight: 700;
}

.ufx-safe-footer__eyebrow {
  margin: 0 0 8px;
  color: #c8f15a;
  font-size: 11px;
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: .15em;
}

.ufx-safe-footer__brand h2 {
  margin: 0;
  color: #fff;
  font-size: 34px;
  line-height: 1.06;
  letter-spacing: -.035em;
  font-weight: 700;
}

.ufx-safe-footer__brand h2 span {
  color: #dafa86;
}

.ufx-safe-footer__intro {
  max-width: 320px;
  margin: 14px 0 0;
  color: rgba(239,245,250,.70);
  font-size: 14px;
  line-height: 1.65;
}

.ufx-safe-footer__cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  margin-top: 18px;
  padding: 9px 15px;
  border: 1px solid #c8f15a;
  border-radius: 999px;
  background: #c8f15a;
  color: #10202d !important;
  text-decoration: none !important;
  font-size: 13px;
  line-height: 1;
  font-weight: 700;
  transition: transform .18s ease, background .18s ease;
}

.ufx-safe-footer__cta:hover {
  transform: translateY(-1px);
  background: #ddff86;
}

.ufx-safe-footer__nav-section {
  min-width: 0;
}

.ufx-safe-footer__nav-section h3 {
  margin: 6px 0 18px;
  color: #fff;
  font-size: 12px;
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: .13em;
  text-transform: uppercase;
}

.ufx-safe-footer__nav-section ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.ufx-safe-footer__tools ul {
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: 30px;
}

.ufx-safe-footer__nav-section li {
  margin: 0 0 12px;
}

.ufx-safe-footer__nav-section a {
  display: inline-flex;
  color: rgba(235,242,248,.72);
  text-decoration: none !important;
  font-size: 14px;
  line-height: 1.4;
  transition: color .18s ease, transform .18s ease;
}

.ufx-safe-footer__nav-section a:hover {
  color: #c8f15a;
  transform: translateX(2px);
}

.ufx-safe-footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  margin-top: 28px;
  padding-top: 16px;
  border-top: 1px solid rgba(255,255,255,.10);
}

.ufx-safe-footer__bottom p {
  margin: 0;
  color: rgba(231,239,246,.58);
  font-size: 12px;
  line-height: 1.45;
}

.ufx-safe-footer__bottom a {
  color: #79aaff;
  text-decoration: none !important;
  font-weight: 600;
}

.ufx-safe-footer__bottom a:hover {
  color: #c8f15a;
}

.ufx-safe-footer__heart {
  color: #ff6570;
}

@media (max-width: 1080px) {
  .ufx-safe-footer__inner {
    width: min(100% - 44px,1320px);
    padding-top: 42px;
  }

  .ufx-safe-footer__top {
    grid-template-columns: 1fr 1.15fr 1fr;
    gap: 36px;
  }

  .ufx-safe-footer__brand {
    grid-column: 1 / -1;
    max-width: 600px;
  }

  .ufx-safe-footer__tools ul {
    column-gap: 24px;
  }
}

@media (max-width: 720px) {
  .ufx-safe-footer__inner {
    width: min(100% - 32px,1320px);
    padding: 38px 0 18px;
  }

  .ufx-safe-footer__top {
    grid-template-columns: 1fr 1fr;
    gap: 32px 24px;
  }

  .ufx-safe-footer__brand {
    grid-column: 1 / -1;
  }

  .ufx-safe-footer__tools {
    grid-column: 1 / -1;
  }

  .ufx-safe-footer__brand h2 {
    font-size: 31px;
  }

  .ufx-safe-footer__logo img,
  .ufx-safe-footer__logo .custom-logo {
    max-width: 190px;
  }

  .ufx-safe-footer__bottom {
    flex-direction: column;
    align-items: flex-start;
    gap: 7px;
    margin-top: 28px;
  }
}

@media (max-width: 460px) {
  .ufx-safe-footer__inner {
    width: min(100% - 28px,1320px);
  }

  .ufx-safe-footer__top {
    grid-template-columns: 1fr;
  }

  .ufx-safe-footer__brand,
  .ufx-safe-footer__tools {
    grid-column: auto;
  }

  .ufx-safe-footer__tools ul {
    grid-template-columns: 1fr 1fr;
    column-gap: 20px;
  }

  .ufx-safe-footer__brand h2 {
    font-size: 29px;
  }

  .ufx-safe-footer__cta {
    width: auto;
  }
}
